import{_ as a,o as e,c as i,a0 as n}from"./chunks/framework.DCluYYrN.js";const h=JSON.parse('{"title":"FoxSu — Kernel root, rebuilt interface","titleTemplate":false,"description":"","frontmatter":{"layout":"home","title":"FoxSu — Kernel root, rebuilt interface","titleTemplate":false,"hero":{"name":"FoxSu","text":"Kernel root, rebuilt interface","tagline":"Root stays in the kernel; the manager was written from scratch. Five skins, thirteen navbar styles, and a customization center that reaches every pixel.","image":{"src":"/logo.png","alt":"FoxSu"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/installation"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/Cmry-mlc/FoxSu"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),l={name:"index.md"};function t(d,s,r,o,c,p){return e(),i("div",null,[...s[0]||(s[0]=[n('<div class="fs-home"><section class="fs-section"><div class="fs-kpis"><div class="fs-kpi"><b>KernelSU</b><span>kernel and ksud from upstream</span></div><div class="fs-kpi"><b>5</b><span>switchable skins</span></div><div class="fs-kpi"><b>13</b><span>navbar pill styles</span></div><div class="fs-kpi"><b>API 37</b><span>Android 12 and above</span></div></div></section><section class="fs-section"><span class="fs-eyebrow">Skins</span><h2 class="fs-title">Five skins, one set of features</h2><p class="fs-lede">Switch under Settings → Appearance and every page follows. Not a wallpaper swap — five different typographic languages.</p><div class="fs-skins"><article class="fs-skin fs-skin--redesign"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Redesign</h3><p>Glass cards with a capsule navbar. Densest layout, default skin.</p></div></article><article class="fs-skin fs-skin--editorial"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Editorial</h3><p>Paper tone, rule lines and serif headings — magazine layout.</p></div></article><article class="fs-skin fs-skin--pages"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Pages</h3><p>Large titles, sectioned lists, generous whitespace.</p></div></article><article class="fs-skin fs-skin--glass"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Glass</h3><p>Liquid glass cards with soft highlights, best over a wallpaper.</p></div></article><article class="fs-skin fs-skin--nocturne"><div class="demo"><span></span><span></span><span></span></div><div class="meta"><h3>Nocturne</h3><p>Dark-first, neon outlines and glowing accents.</p></div></article></div></section><section class="fs-section"><span class="fs-eyebrow">Navigation</span><h2 class="fs-title">The navbar is no longer tied to the skin</h2><p class="fs-lede">Thirteen capsule styles, selectable globally. The side-drawer mode reserves space on the left so content is never covered.</p><div class="fs-pills"><span class="fs-pill is-active">Original capsule</span><span class="fs-pill">Expanded pill</span><span class="fs-pill">Side drawer</span><span class="fs-pill">Glow cursor</span><span class="fs-pill">Neon outline</span><span class="fs-pill">Block cards</span><span class="fs-pill">Gradient solid</span><span class="fs-pill">Top indicator</span><span class="fs-pill">Floating disc</span><span class="fs-pill">Paper rule</span><span class="fs-pill">White pill</span><span class="fs-pill">Liquid pill</span><span class="fs-pill">Nocturne neon</span></div></section><section class="fs-section"><span class="fs-eyebrow">Customization</span><h2 class="fs-title">Customization center</h2><p class="fs-lede">Every appearance option is wired to a real setting and applies instantly. No restart.</p><div class="fs-grid"><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f58ba8,#f7a98c);"></div><h3>Wallpaper</h3><p>Pick, crop, zoom and dim — or turn the global background off entirely.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f5ce7e,#a8d8a0);"></div><h3>Card artwork</h3><p>Give the hero card, the four KPI cards and each module card its own image and opacity.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#8fc9e8,#b49be0);"></div><h3>Card colors</h3><p>Global color picking plus per-card overrides, independent alpha, one-tap rainbow.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#b49be0,#f58ba8);"></div><h3>Typography</h3><p>System, serif, monospace or rounded handwriting — or import your own font file.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#a8d8a0,#8fc9e8);"></div><h3>Title and icon</h3><p>Custom home title, four fox launcher icons that follow the system theme.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f7a98c,#f5ce7e);"></div><h3>Radius and light</h3><p>Corner radius, opacity, icon shape, immersive glow and liquid glass — each adjustable.</p></div></div></section><section class="fs-section"><span class="fs-eyebrow">Root</span><h2 class="fs-title">The part that does the work is still in the kernel</h2><p class="fs-lede">su, the allowlist, App Profile, module mounting and sucompat all come from the kernel module and ksud. The manager is the visible layer.</p><div class="fs-grid"><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f58ba8,#b49be0);"></div><h3>Allowlist</h3><p>Only permitted apps can obtain su; everything else stays unaware root exists.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#8fc9e8,#a8d8a0);"></div><h3>App Profile</h3><p>Per-uid uid, gid, groups, capabilities and SELinux context — saveable as reusable templates.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f5ce7e,#f58ba8);"></div><h3>Module repository</h3><p>Built-in index to browse, search, inspect and install. Removals can be undone.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#b49be0,#8fc9e8);"></div><h3>Kernel umount</h3><p>Unmount modules in the kernel so userspace sees no trace, paired with hidden SELinux changes.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#a8d8a0,#f5ce7e);"></div><h3>SU Log</h3><p>Grants and denials are written to sulog and readable inside the manager.</p></div><div class="fs-card"><div class="fs-dot" style="background:linear-gradient(135deg,#f7a98c,#b49be0);"></div><h3>Install and diagnose</h3><p>Single-screen installer, dedicated flash page, crash logs and soft reboot.</p></div></div></section><section class="fs-cta"><h2>Kernel first, then root</h2><p>Installing the APK alone does not grant root — your device kernel must include the FoxSu / KernelSU driver. GKI 2.0 (kernel 5.10+) is supported out of the box; older kernels need a self-built kernel.</p><div class="fs-actions"><a class="VPButton medium brand" href="https://github.com/Cmry-mlc/FoxSu/releases">Download manager APK</a><a class="VPButton medium alt" href="./guide/installation.html">Read the install guide</a></div></section></div>',1)])])}const v=a(l,[["render",t]]);export{h as __pageData,v as default};
